 "content": "from collections import Counter


def transform(grid):
    """Compare the two stacked copies, align their one-column offset, and
    color the incomplete copy's missing foreground continuations with 1."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    active = [any(v != bg for v in row) for row in grid]
    runs = []
    r = 0
    while r < h:
        if not active[r]:
            r += 1
            continue
        start = r
        while r < h and active[r]:
            r += 1
        runs.append((start, r))
    if len(runs) < 2:
        return [row[:] for row in grid]
    (top0, top1), (bot0, bot1) = runs[0], runs[-1]
    n = min(top1 - top0, bot1 - bot0)

    # lower[c] corresponds to upper[c-offset]; choose the offset with
    # the greatest agreement across corresponding rows.
    best_offset = 0
    best_score = float('inf')
    for offset in range(-2, 3):
        mismatches = total = 0
        for k in range(n):
            for c in range(w):
                u = c - offset
                if 0 <= u < w:
                    mismatches += ((grid[bot0 + k][c] != bg) !=
                                   (grid[top0 + k][u] != bg))
                    total += 1
        score = mismatches / max(total, 1)
        if score < best_score:
            best_score, best_offset = score, offset

    offset = best_offset
    upper_extra = []  # upper foreground missing from the aligned lower copy
    lower_extra = []  # lower foreground missing from the aligned upper copy
    for k in range(n):
        for c in range(w):
            u = c - offset
            if 0 <= u < w:
                up = grid[top0 + k][u] != bg
                lo = grid[bot0 + k][c] != bg
                if up and not lo:
                    upper_extra.append((k, u))
                elif lo and not up:
                    lower_extra.append((k, c))

    out = [row[:] for row in grid]
    # The copy with more unmatched foreground is the complete reference;
    # paint the corresponding missing cells in the other copy.
    if len(lower_extra) > len(upper_extra):
        for k, c in lower_extra:
            u = c - offset
            if 0 <= u < w and out[top0 + k][u] == bg:
                out[top0 + k][u] = 1
    else:
        for k, u in upper_extra:
            c = u + offset
            if 0 <= c < w and out[bot0 + k][c] == bg:
                out[bot0 + k][c] = 1
    return out
